export function truncate(text, max) {
  if (max <= 0) return '';
  if (text.length <= max) return text;
  if (max <= 3) return '.'.repeat(max);
  return text.slice(0, max - 3) + '...';
}

test('short text is left alone', () => assert.equal(truncate('hi', 5), 'hi'));
test('cut text stays within max and ends with an ellipsis', () => {
  const result = truncate('hello world', 5);
  assert.ok(result.length <= 5);
  assert.ok(result.endsWith('...'));
  assert.equal(result, 'he...');
});
test('small max values never exceed max', () => {
  for (const max of [0, 1, 2, 3]) {
    const result = truncate('hello world', max);
    assert.ok(result.length <= max, `max ${max} returned ${JSON.stringify(result)}`);
  }
});
test('max of three returns the ellipsis', () => assert.equal(truncate('hello', 3), '...'));
test('text exactly max long is unchanged', () => assert.equal(truncate('hello', 5), 'hello'));
test('capitalize raises the first letter', () => assert.equal(capitalize('ab'), 'Ab'));

